import { BunServices } from '@effect/platform-bun';
import { Effect } from 'effect';
import { TestClock } from 'effect/testing';
import { exportComparison } from './src/export.ts';
import { parseCapture } from './src/capture/model.ts';
const fixture = 'tests/fixtures/self-observe';
const capture = await Effect.runPromise(parseCapture(await Bun.file(`${fixture}/candidate/capture.json`).text()));
const exported = await Effect.runPromise(Effect.gen(function* () {
  yield* TestClock.setTime(Date.parse(capture.finishedAt));
  return yield* exportComparison({
    journeys: [{ baseDirectory: `${fixture}/base`, candidateDirectory: `${fixture}/candidate` }],
    directory: 'self-observe',
    viewerDirectory: 'dist/viewer'
  });
}).pipe(Effect.provide(TestClock.layer()), Effect.provide(BunServices.layer)));
if (exported.result.conclusion.kind !== 'regression') throw new Error(`The fixture must read as a regression, got ${exported.result.conclusion.kind}`);
